// ── Build one Firecrawl search query per requested B2C source ─────────────
// Supports: reddit | yelp | youtube | twitter | google
const raw = $input.first().json;
const body = raw.body ?? raw;

const industry   = (body.industry ?? body.target_description ?? 'local services').trim();
const location   = (body.location ?? '').trim();
const sources    = body.b2c_sources ?? ['reddit', 'yelp'];
const keywords   = (body.keywords ?? []).slice(0, 4).join(' OR ');
const context = {
  run_id:       body.run_id,
  org_id:       body.org_id,
  callback_url: body.callback_url,
  industry,
  location,
  service:      body.client_service ?? industry,
};

const locStr = location ? ` "${location}"` : '';
const kwStr  = keywords ? ` ${keywords}` : '';

const QUERIES = {
  reddit:
    `site:reddit.com "${industry}"${locStr} (recommend OR "looking for" OR advice OR help OR "who should I" OR "best")${kwStr}`,
  yelp:
    `site:yelp.com "${industry}"${locStr} review${kwStr}`,
  youtube:
    `site:youtube.com "${industry}"${locStr} (review OR recommend OR "how to find" OR best)${kwStr}`,
  twitter:
    `(site:x.com OR site:twitter.com) "${industry}"${locStr} (recommend OR looking OR need OR help)${kwStr}`,
  google:
    `"${industry}" ${location} (recommend OR review OR "looking for" OR "need a" OR "best")${kwStr}`,
};

const items = sources
  .filter(s => QUERIES[s])
  .map(source => ({
    json: {
      ...context,
      source,
      query: QUERIES[source],
    }
  }));

return items.length ? items : [{ json: { ...context, source: 'google', query: QUERIES.google } }];

// Flatten the Firecrawl response into individual result items,
// tagging each with its source and the discovery context.
const ctx = $json;  // has source, run_id, org_id, industry, location, etc.
const results = ctx.data ?? [];

if (!results.length) return [];

return results.map(r => ({
  json: {
    run_id:   ctx.run_id,
    org_id:   ctx.org_id,
    callback_url: ctx.callback_url,
    source:   ctx.source,
    industry: ctx.industry,
    location: ctx.location,
    service:  ctx.service,
    url:    r.url ?? '',
    title:  r.title ?? '',
    content: ((r.markdown ?? r.description ?? '')
      .replace(/\n{3,}/g, '\n\n')
      .slice(0, 800)),
  }
}));

