// Parse GPT response, validate signals, add HMAC signature for callback
const crypto = require('crypto');

const gptResp = $input.first().json;
const raw = gptResp?.choices?.[0]?.message?.content ?? '[]';

let signals = [];
try {
  const clean = raw.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  const parsed = JSON.parse(clean);
  signals = Array.isArray(parsed) ? parsed : (parsed.signals ?? parsed.intent_signals ?? []);
} catch(e) {
  signals = [];
}

// Pull context from the first aggregated item
const allItems = $('Aggregate All Results').all();
const ctx = allItems?.[0]?.json?.data?.[0] ?? {};

const payload = {
  run_id:          ctx.run_id ?? '',
  org_id:          ctx.org_id ?? '',
  workflow_type:   'intent_discovery',
  status:          'complete',
  intent_signals:  signals.slice(0, 50),
  output: {
    signals_found: signals.length,
    sources_scanned: [...new Set(signals.map(s => s.source))],
  },
};

const payloadStr = JSON.stringify(payload);
const hmacSecret = $env.N8N_HMAC_SECRET ?? 'dev-secret';
const signature  = crypto.createHmac('sha256', hmacSecret).update(payloadStr).digest('hex');

return [{
  json: {
    payload,
    payloadStr,
    signature,
    callback_url: ctx.callback_url ?? '',
  }
}];

// Error handler — post failure callback to SignafyAI
const crypto = require('crypto');

// Try to grab context from any available input
const item = $input.first()?.json ?? {};
const runId = item.run_id ?? item.body?.run_id ?? '';
const orgId = item.org_id ?? item.body?.org_id ?? '';
const callbackUrl = item.callback_url ?? item.body?.callback_url ?? '';

if (!callbackUrl) return [{ json: { skipped: true } }];

const payload = {
  run_id:        runId,
  org_id:        orgId,
  workflow_type: 'intent_discovery',
  status:        'failed',
  error_message: 'WF2 B2C Consumer Intent Finder encountered an error',
};

const payloadStr = JSON.stringify(payload);
const hmacSecret = $env.N8N_HMAC_SECRET ?? 'dev-secret';
const signature  = crypto.createHmac('sha256', hmacSecret).update(payloadStr).digest('hex');

return [{ json: { payloadStr, signature, callback_url: callbackUrl } }];
